package br.com.bancohorizonte.service;
import br.com.bancohorizonte.entity.*; import br.com.bancohorizonte.exception.*; import org.junit.jupiter.api.*; import java.math.BigDecimal; import static org.junit.jupiter.api.Assertions.*;
class MovimentacaoServiceTest { private final MovimentacaoService service=new MovimentacaoService(); private ContaBancaria conta(BigDecimal saldo,boolean ativa){return new ContaBancaria("0001","123456-7",saldo,ativa,new Pessoa("Camila","55566677788","camila@example.com"),new TipoConta("CORRENTE"));} @Test void depositoValido(){ContaBancaria c=conta(new BigDecimal("100.00"),true);service.depositar(c,new BigDecimal("50.00"));assertEquals(0,new BigDecimal("150.00").compareTo(c.getSaldo()));} @Test void saqueValido(){ContaBancaria c=conta(new BigDecimal("100.00"),true);service.sacar(c,new BigDecimal("75.50"));assertEquals(0,new BigDecimal("24.50").compareTo(c.getSaldo()));} @Test void saqueSemSaldo(){assertThrows(SaldoInsuficienteException.class,()->service.sacar(conta(new BigDecimal("10.00"),true),new BigDecimal("10.01")));} @Test void valorInvalido(){assertThrows(ValorMovimentacaoInvalidoException.class,()->service.depositar(conta(BigDecimal.ZERO,true),BigDecimal.ZERO));} @Test void contaInativa(){assertThrows(ContaInativaException.class,()->service.depositar(conta(BigDecimal.ZERO,false),BigDecimal.ONE));} }
